import Vue from 'vue'
import Router from 'vue-router'

Vue.use(Router)

const router = new Router({
  // mode: 'history',
  base: process.env.BASE_URL,
  routes: [
    {
      path: '/add_template',
      name: 'add_template',
      component: () => import('./pages/add_template.vue'),
      meta: {
        title: '添加模板'
      }
    },
    {
      path: '/',
      name: 'template_list',
      component: () => import('./pages/template_list.vue'),
      meta: {
        title: '模板列表'
      }
    },
    {
      path: '/template_list',
      name: 'template_list',
      component: () => import('./pages/template_list.vue'),
      meta: {
        title: '模板列表'
      }
    },
    {
      path: '/template_write',
      name: 'template_write',
      component: () => import('./pages/template_write.vue'),
      meta: {
        title: '填写内容'
      }
    },
    {
      path: '/write_list',
      name: 'write_list',
      component: () => import('./pages/write_list.vue'),
      meta: {
        title: '填写记录列表'
      }
    }
  ]
})

// 全局路由守卫
router.beforeEach((to, from, next) => {
  console.log('navigation-guards', to, from);
  if (to.meta.title) {
    document.title = to.meta.title
  }
  next()
})

export default router
